<?php
declare(strict_types=1);
require dirname(__DIR__).'/bootstrap.php';
use Omnigo\{Database,MarketplaceGate,HttpError};
function check(bool $ok,string $label):void{if(!$ok)throw new RuntimeException($label);}
function blocked(callable $work,int $status):void{try{$work();throw new RuntimeException('Koruma atlandı.');}catch(HttpError $e){check($e->getCode()===$status,$e->getMessage());}}
$db=new Database(['dsn'=>'sqlite::memory:']);$db->pdo->exec(file_get_contents(__DIR__.'/schema.sqlite.sql'));MarketplaceGate::install($db);
$db->run("INSERT INTO companies VALUES(1,'Birinci'),(2,'İkinci')");
$db->run("INSERT INTO users VALUES(1,'a@example.test','Yetkili','x','admin',NULL),(2,'b@example.test','Yetkili 2','x','admin',NULL),(3,'c@example.test','Müşteri','x','client',1)");
$admin=['id'=>1,'role'=>'admin','token'=>str_repeat('a',64)];$other=['id'=>2,'role'=>'admin','token'=>str_repeat('b',64)];$client=['id'=>3,'role'=>'client'];
foreach([$admin,$other] as $u)$db->run('INSERT INTO sessions VALUES(?,?,?,?)',[$u['token'],$u['id'],'csrf',time()+28800]);
$clock=time();$gate=new MarketplaceGate($db,static function()use(&$clock){return $clock;});$password='Synthetic-Management-2026!';
blocked(fn()=>$gate->require($admin,1),423);
blocked(fn()=>$gate->workspaceAccess($admin,2),423);
blocked(fn()=>$gate->workspaceAccess($client,1),403);
$first=$gate->unlock($admin,1,['password'=>$password,'confirmation'=>$password,'setup'=>true]);
check(strlen($first['grant'])===64,'Opak doğrulama anahtarı döner.');
check($gate->status($admin,1)['granted'],'Doğrulanan kullanıcının sunucu izni tarayıcı anahtarından bağımsızdır.');
check($gate->status($admin,1,$first['grant'])['granted'],'Doğrulanan bölüm açılır.');
check($gate->status($admin,2,$first['grant'])['granted'],'Aynı kullanıcı üç alana ve diğer mağazaya 15 dakika tekrar şifresiz geçer.');
check($gate->workspaceAccess($admin,2)['companyId']===2,'Müşteri geçişi aynı ortak 15 dakikalık doğrulamayı kullanır.');
check($gate->workspaceAccess($admin,2)['expiresAt']===$first['expiresAt'],'Müşteri seçimi süreyi uzatmaz.');
blocked(fn()=>$gate->workspaceAccess($other,2),423);
blocked(fn()=>$gate->workspaceAccess($admin,999),404);
check(!$gate->status($other,1,$first['grant'])['granted'],'Anahtar başka hesaba taşınmaz.');
check(!$gate->status($other,1,str_repeat('f',64))['granted'],'Uydurma anahtar farklı kullanıcıya erişim vermez.');
blocked(fn()=>$gate->unlock($other,1,['password'=>'Wrong']),403);
$second=$gate->unlock($other,1,['password'=>$password]);check($gate->status($other,1,$second['grant'])['granted'],'Aynı ortak şifre diğer Omnigo yetkilisinde çalışır.');
blocked(fn()=>$gate->status($client,1,$first['grant']),403);
$stored=$db->one('SELECT session_key,expires FROM marketplace_admin_grants WHERE company_id=0');
check($stored['session_key']!==$first['grant']&&$stored['session_key']!==$admin['token'],'Sunucuda ham anahtar veya oturum yerine bağlı karma tutulur.');
check((int)$stored['expires']===$clock+900,'Süre tam 15 dakikadır; sekiz saatlik oturuma bağlanmaz.');
$_SERVER['HTTP_X_OMNIGO_MANAGEMENT_GRANT']=$first['grant'];$gate->require($admin,1);$gate->require($admin,1);
$gate->revoke($admin,1,$first['grant']);blocked(fn()=>$gate->require($admin,1),423);
$reopened=$gate->unlock($admin,1,['password'=>$password]);check($reopened['grant']!==$first['grant'],'Yeniden açılış yeni anahtar alır.');
check($gate->status($admin,1)['granted'],'Yeni doğrulama sunucuda kullanıcı iznini açar.');
$global=$gate->unlock($admin,0,['password'=>$password]);check($gate->status($admin,2,$global['grant'])['granted'],'Kullanıcı yönetiminde doğrulanan genel akış alt müşteri ekranlarını kapsar.');
$gate->revoke($admin,0,$global['grant']);check(!$gate->status($admin,2,$global['grant'])['granted'],'Genel akış kapatılınca alt ekran da kilitlenir.');
$resumed=$gate->unlock($admin,1,['password'=>$password]);$expires=$resumed['expiresAt'];
$db->run('DELETE FROM sessions WHERE token=?',[$admin['token']]);check(!$gate->status($admin,1)['granted'],'Giriş yapılmadan yönetim izni kullanılamaz.');
blocked(fn()=>$gate->unlock($admin,1,['password'=>$password]),401);
$admin['token']=str_repeat('c',64);$db->run('INSERT INTO sessions VALUES(?,?,?,?)',[$admin['token'],$admin['id'],'csrf',time()+28800]);
$clock=$expires-1;check($gate->status($admin,2)['granted'],'Uygulama kapanıp yeni oturumla girilse de son saniyeye kadar izin korunur.');
check($gate->workspaceAccess($admin,2)['allowed'],'899. saniyede uygulama yeniden açılsa da müşteri geçişi şifresiz doğrulanır.');
check($gate->status($admin,2)['expiresAt']===$expires,'Okuma, müşteri değişimi ve yeniden giriş süreyi uzatmaz.');
$clock=$expires;blocked(fn()=>$gate->require($admin,1),423);check(!$gate->status($admin,2)['granted'],'Tam 900 saniyede tüm korumalı yollar kilitlenir.');
blocked(fn()=>$gate->workspaceAccess($admin,2),423);
$fresh=$gate->unlock($admin,1,['password'=>$password]);check($fresh['expiresAt']===$clock+900,'Yeni şifre doğrulaması yeni 15 dakika başlatır.');
$db->run('UPDATE marketplace_admin_lock SET password_hash=?',[Omnigo\Security::hashPassword('Another-Synthetic-2026!')]);check(!$gate->status($admin,1)['granted'],'Ortak şifre değişirse eski izin kullanılamaz.');
foreach(['/api/management/permissions','/api/management/customer','/api/management/marketplaces','/api/management/marketplaces-bulk','/api/management/users/3','/api/management/users/3/password','/api/management/initial-password','/api/management/permissions-bulk','/api/admin/users','/api/admin/users/3/portrait','/api/integrations/hepsiburada/credentials'] as $path)check(MarketplaceGate::protects($path),'Alternatif yol korunur: '.$path);
check(MarketplaceGate::protects('/api/users','POST'),'Alternatif kullanıcı ekleme korunur.');
check(!MarketplaceGate::protects('/api/management/logo','GET')&&MarketplaceGate::protects('/api/management/logo','POST'),'Logo görüntüleme açık; logo değiştirme korumalı.');
foreach(['/api/inventory','/api/push/desktop/poll','/api/workspace/revision','/api/admin/connection-health','/api/dashboard'] as $path)check(!MarketplaceGate::protects($path),'Canlı işleyişe yeni kilit eklenmez.');
unset($_SERVER['HTTP_X_OMNIGO_MANAGEMENT_GRANT']);
echo "Ortak yönetim şifresi: bölüm ömrü, tekrar kayıt, kapatma/yeniden açma, oturum/mağaza ayrımı ve alternatif yollar geçti.\n";
